pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackerSeed) public {
        // keep amounts reasonable
        amount = bound(amount, 1, 1000 ether);
        vm.assume(attackerSeed != address(this) && attackerSeed != address(c) && attackerSeed != 0);

        // deploy a re-entrant attacker contract whose receive callback calls withdrawBalance again
        ReenteringAttacker attacker = new ReenteringAttacker(c);
        address attackerAddr = address(attacker);
        vm.deal(attackerAddr, amount);

        // attacker deposits
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();

        // attacker initiates withdraw; receive() will re-enter addToBalance
        uint256 balanceBefore = address(attackerAddr).balance;
        vm.prank(attackerAddr);
        attacker.start();
        uint256 balanceAfter = address(attackerAddr).balance;

        // C invariant: attacker should never end up with more than (initial balance + deposited amount)
        // i.e., total drained must not exceed its own balance before the withdrawal.
        uint256 deposited = amount;
        // The actual balance of attacker in C after all calls is given by getBalance
        uint256 userBalAfter = c.getBalance(attackerAddr);

        // Reference: re-entrancy is prevented → attacker can only withdraw exactly its balance once.
        // So attacker balance after must be <= attackerBalanceBefore + deposited (withdraw of its own deposit)
        // Bug: re-entrancy allows double withdraw → attackerBalanceAfter will be > attackerBalanceBefore + deposited.
        assertTrue(balanceAfter <= address(attacker).balance + deposited);
    }
}

contract ReenteringAttacker {
    C public target;
    bool private called;
    constructor(C _target) { target = _target; }
    function start() external payable {
        called = false;
        target.withdrawBalance();
    }
    receive() external payable {
        if (!called) {
            called = true;
            target.addToBalance{value: 0}();
        }
    }
}

