pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to feasible range that avoids overflow reverts and zero-value noise
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 1 ether, depositAmount);

        // Deploy a re-entrant attacker that calls addToBalance from its receive fallback
        Attacker attacker = new Attacker(address(c));

        // Fund the attacker and the contract
        vm.deal(address(attacker), depositAmount);
        vm.deal(address(c), withdrawAmount); // needed for withdrawBalance to send Ether back

        // 1. Attacker deposits to get a balance
        vm.prank(address(attacker));
        c.addToBalance{value: depositAmount}();

        // 2. Attacker starts a withdraw that triggers re-entrant addToBalance
        vm.prank(address(attacker));
        c.withdrawBalance();

        // After the re-entrant call, check the locked_ state (readable via a manual getter? No, locked_ is internal.
        // Instead we observe the invariant: the re-entrant addToBalance call should have been blocked if nonReentrant is correct.
        // In the reference, locked_ is true during withdrawBalance, so re-entrant addToBalance fails (require locked_ == false).
        // In the bug, locked_ is not set on entry, so re-entrant addToBalance executes.
        // Evidence: the contract's balance after the call — a successful re-entrant addToBalance deposits funds again,
        // increasing contract balance beyond the single deposit.
        uint256 finalContractBalance = address(c).balance;
        // The attacker only deposited once; if re-entrancy succeeded, contract has > depositAmount.
        // Property: The contract balance never exceeds the sum of all single deposits (no double deposit via re-entrancy).
        // After a single deposit and a re-entrant attempt, the balance should be <= depositAmount.
        assertTrue(finalContractBalance <= depositAmount);
    }
}

contract Attacker {
    C public target;
    bool private reentered;

    constructor(address _target) {
        target = C(_target);
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // Re-enter addToBalance to attempt double deposit
            target.addToBalance{value: msg.value}();
        }
    }

    receive() external payable {
        this.fallback{value: msg.value}();
    }
}

