import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 attackAmount) public {
        // Bound parameters to reasonable range to avoid overflow issues
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(attackAmount > 0 && attackAmount < type(uint128).max);

        // Deploy reentrant attacker
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), attackAmount + depositAmount);

        // Attacker deposits some Ether
        attacker.deposit(depositAmount);

        // Attacker attempts reentrancy attack
        attacker.attack(attackAmount);

        // Invariant: The sum of all balances ≤ total Ether ever received by c
        // After any sequence, no user's balance exceeds contract's total received Ether.
        // We track total received via contract balance + total withdrawn (which we simulate via attacker's balance getter)
        uint256 contractBalance = address(c).balance;
        uint256 attackerBalance = c.getBalance(address(attacker));

        // The bug allows inflating a balance beyond what was deposited
        // In correct version, attackerBalance ≤ total Ether sent to c (depositAmount only)
        // In buggy version, reentrant addToBalance during withdrawBalance can inflate without Ether
        assertTrue(attackerBalance <= depositAmount + attackAmount);
    }
}

