pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 attackerBalance) public {
        // Restrict to reasonable ranges to avoid overflow issues in depositing large numbers
        vm.assume(depositAmount > 0 && depositAmount <= 100 ether);
        vm.assume(attackerBalance >= depositAmount && attackerBalance <= 1000 ether);

        // Deploy a reentrant attacker contract that will call withdrawBalance again during its receive hook
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address attackerAddr = address(attacker);

        // Fund the attacker with enough ETH to make the initial deposit
        vm.deal(attackerAddr, attackerBalance);

        // Attacker makes a deposit via addToBalance
        vm.prank(attackerAddr);
        c.addToBalance{value: depositAmount}();

        // Now attacker initiates a withdrawal, which triggers the reentrancy in the receive callback
        vm.prank(attackerAddr);
        attacker.attack();

        // After the attack, the contract's ETH balance should be 0 (since all balances withdrawn),
        // and the sum of all user balances (recorded in mapping) should also be 0.
        // The invariant: address(c).balance == sum of all user balances.
        // In the buggy version, extra ETH is stolen, so address(c).balance would be 0 but recorded balance of attacker might
        // still be non-zero (or the invariant doesn't hold). We check that the attacker's recorded balance matches
        // the contract's ETH balance (since only one user).
        uint256 contractBalance = address(c).balance;
        uint256 recordedBalance = c.getBalance(attackerAddr);

        // The invariant: recorded balance for attacker should be at least the contract balance
        // (if no other users, they should be equal). Buggy version will have recordedBalance > contractBalance.
        assertTrue(recordedBalance == contractBalance);
    }
}

contract ReentrantAttacker {
    C target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        attacking = true;
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Reenter only once to drain extra funds
            target.withdrawBalance();
        }
    }
}

