pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound amounts to avoid overflow in test and keep within reasonable range
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(withdrawAmount > 0 && withdrawAmount < type(uint256).max / 2);

        // Deploy a re-entrant attacker that will call withdrawBalance() again
        ReEntrantAttacker attacker = new ReEntrantAttacker(address(c));
        address attackerAddr = address(attacker);

        // Give attacker some ETH to deposit
        vm.deal(attackerAddr, depositAmount);
        vm.prank(attackerAddr);
        c.addToBalance{value: depositAmount}();

        // Record contract balance and user balance sum before withdrawal
        uint256 contractBalanceBefore = address(c).balance;
        uint256 attackerBalanceBefore = c.getBalance(attackerAddr);
        uint256 sumUserBalancesBefore = c.getBalance(attackerAddr);

        // Trigger the withdrawal through the attacker, which re-enters withdrawBalance
        // The attacker's receive function will call withdrawBalance again up to 3 times
        vm.prank(attackerAddr);
        attacker.attack();

        // After withdrawal, compute contract balance and sum of user balances
        uint256 contractBalanceAfter = address(c).balance;
        uint256 attackerBalanceAfter = c.getBalance(attackerAddr);
        uint256 sumUserBalancesAfter = attackerBalanceAfter;

        // Property: contract balance should never be less than the sum of all user balances
        // Reference pass: balance = sum. Buggy fail: balance < sum (drained extra).
        assertTrue(contractBalanceAfter >= sumUserBalancesAfter);
    }
}

contract ReEntrantAttacker {
    C public target;
    uint8 private reentryCount = 0;

    constructor(address _target) {
        target = C(_target);
    }

    function attack() external payable {
        target.withdrawBalance();
    }

    receive() external payable {
        if (reentryCount < 3 && address(target).balance > 0) {
            reentryCount++;
            target.withdrawBalance();
        }
    }
}
